    // E1B-04 (edit while pending): a REAL Human edit invalidates the
    // in-flight probe (not_tested + best-effort cancel); the late completion
    // from the key-A request is ignored.
    void e1b04_editWhilePendingInvalidatesProbe()
    {
        FakeQmlAsyncTestConnectionClient fake;
        PageObjects page = loadRealPage();
        QVERIFY(page.page != nullptr);
        QVERIFY(page.controller != nullptr && page.field != nullptr
                && page.box != nullptr);
        QQuickItem *testButton = page.page->findChild<QQuickItem *>(
            QStringLiteral("aiTestConnectionButton"));
        QVERIFY(testButton != nullptr);

        page.controller->setAsyncTestConnectionClientForAutomation(&fake);

        const QStringList providers = page.controller->availableProviders();
        activateProvider(page.box, providers.indexOf(QStringLiteral("DeepSeek")));
        page.controller->setProperty("modelText", QStringLiteral("model-b"));
        humanEditField(page.field, QStringLiteral("FAKE_U2_KEY_A"));

        QVERIFY(clickTestConnectionButton(testButton));
        QCOMPARE(page.controller->property("connectionStatusToken").toString(),
                 QStringLiteral("testing"));
        const int cancelBefore = fake.cancelCount;

        // REAL Human edit to key B through the QML seam.
        humanEditField(page.field, QStringLiteral("FAKE_U2_KEY_B"));
        QCOMPARE(page.controller->property("connectionStatusToken").toString(),
                 QStringLiteral("not_tested"));
        QCOMPARE(fake.cancelCount, cancelBefore + 1);
        QCOMPARE(page.field->property("text").toString(),
                 QStringLiteral("FAKE_U2_KEY_B"));

        // LATE completion from the key-A request: ignored.
        fake.finishPendingWithResult(probeResult(QStringLiteral("connection_ok")));
        QCOMPARE(page.controller->property("connectionStatusToken").toString(),
                 QStringLiteral("not_tested"));
    }

