    // E1B-10 (failure presentation): representative sanitized failure — no
    // raw body/URL/Authorization/secret, field unchanged, no Save mutation.
    void e1b10_failurePresentation()
    {
        FakeQmlAsyncTestConnectionClient fake;
        PageObjects page = loadRealPage();
        QVERIFY(page.page != nullptr);
        QVERIFY(page.controller != nullptr && page.field != nullptr
                && page.box != nullptr);
        QQuickItem *testButton = page.page->findChild<QQuickItem *>(
            QStringLiteral("aiTestConnectionButton"));
        QVERIFY(testButton != nullptr);

        page.controller->setAsyncTestConnectionClientForAutomation(&fake);

        const QStringList providers = page.controller->availableProviders();
        activateProvider(page.box, providers.indexOf(QStringLiteral("DeepSeek")));
        page.controller->setProperty("modelText", QStringLiteral("model-b"));
        page.field->setProperty("text", QString::fromUtf8(kU2NewFakeSecret));
        const QString saveStatusBefore =
            page.controller->property("saveStatusToken").toString();

        QVERIFY(clickTestConnectionButton(testButton));
        fake.finishPendingWithResult(probeResult(QStringLiteral("auth_failed")));

        QCOMPARE(page.controller->property("connectionStatusToken").toString(),
                 QStringLiteral("auth_failed"));
        QObject *statusItem = page.page->findChild<QObject *>(
            QStringLiteral("aiConnectionStatus"));
        // E1b-C (Issue A, Human-frozen wording): the tested key may be a
        // TRANSIENT unsaved value OR the stored one — the presentation must
        // be source-neutral and must NOT claim it was the saved key.
        // (Pre-fix REAL RED: the old wording claimed "已保存的 Key".)
        QCOMPARE(statusItem->property("text").toString(),
                 QStringLiteral("API Key 验证失败，请核对当前 API Key"));
        QVERIFY(statusItem->property("text").toString()
                    != QString::fromUtf8(kU2NewFakeSecret));
        QVERIFY(!page.field->property("text").toString().isEmpty());
        QCOMPARE(page.controller->property("saveStatusToken").toString(),
                 saveStatusBefore);
    }

    // E1b-C §3 (source-neutrality control, GREEN pre- AND post-fix): the
    // auth_failed wording must be IDENTICAL whether the tested secret came
    // from the transient field or from the stored credential — the UI must
    // not reveal which source was used.
    void e1bc02_authFailureWordingSourceNeutral()
    {
        FakeQmlAsyncTestConnectionClient fake;
        PageObjects page = loadRealPage();
        QVERIFY(page.page != nullptr);
        QVERIFY(page.controller != nullptr && page.field != nullptr
                && page.box != nullptr);
        QQuickItem *testButton = page.page->findChild<QQuickItem *>(
            QStringLiteral("aiTestConnectionButton"));
        QVERIFY(testButton != nullptr);

        page.controller->setAsyncTestConnectionClientForAutomation(&fake);

        const QStringList providers = page.controller->availableProviders();
        activateProvider(page.box, providers.indexOf(QStringLiteral("DeepSeek")));
        page.controller->setProperty("modelText", QStringLiteral("model-b"));
        QObject *statusItem = page.page->findChild<QObject *>(
            QStringLiteral("aiConnectionStatus"));
        QVERIFY(statusItem != nullptr);

        // Source 1: TRANSIENT unsaved key (auth failure).
        page.field->setProperty("text", QString::fromUtf8(kU2NewFakeSecret));
        QVERIFY(clickTestConnectionButton(testButton));
        fake.finishPendingWithResult(probeResult(QStringLiteral("auth_failed")));
        const QString transientWording = statusItem->property("text").toString();
        QVERIFY(!transientWording.isEmpty());

        // Source 2: STORED credential (blank field), same auth failure.
        page.field->setProperty("text", QString()); // programmatic blank
        QVERIFY(clickTestConnectionButton(testButton));
        fake.finishPendingWithResult(probeResult(QStringLiteral("auth_failed")));
        const QString storedWording = statusItem->property("text").toString();

        // Single mapping → identical source-neutral wording.
        QCOMPARE(storedWording, transientWording);
        QVERIFY(!storedWording.isEmpty());
    }

